                    self.state.m_dbout = (self.state.m_aluo) & 0xffff;
                    self.state.m_au = (self.state.m_au).wrapping_sub(4);
                    // alu r=6 c=1 m=.....  i=.l..... 1 a=37:m_ftu d=-1
                    self.alu_and(self.state.m_ftu, 0xffff);
                    self.state.m_base_ssw = (SSW_DATA) & 0xffff;
                    self.write_data(bus, self.state.m_aob & !1, self.state.m_dbout, 0xffff);
                    self.m_icount -= 4;
                    if self.m_icount <= 0 {
                    if self.access_to_be_redone() {
                    self.m_icount += 4;
                    self.state.m_inst_substate = 1;
                    } else {
                    self.state.m_inst_substate = 2;
                    }
                    return;
                    }
                    if (self.state.m_aob & 1) != 0 {
                    self.m_icount -= 4;
                    self.state.m_inst_state = S_ADDRESS_ERROR;
                    return;
                    }
                    // 360 trap4
                    self.state.m_aob = self.state.m_au;
                    self.state.m_dbout = (self.state.m_aluo) & 0xffff;
                    self.debugger_exception_hook(0x06);
                    self.state.m_da[16] = self.state.m_au;
                    self.state.m_ftu = (0x0018) & 0xffff;
                    self.state.m_au = (self.state.m_au).wrapping_add(2);
