    fn reset_if<B: Bus>(&mut self, bus: &mut B) {
        const ENTRY: u32 = 0;
        const RSET3: u32 = 1;
        const RSET5: u32 = 2;
        let mut label = ENTRY;
        loop {
            match label {
                ENTRY => {
                    if (self.state.m_sr & SR_S) == 0 {
                    self.state.m_inst_state = S_PRIVILEDGE;
                    return;
                    }
                    // 3a6 rset1
                    self.state.m_ird = (self.state.m_ir) & 0xffff;
                    if self.state.m_next_state != S_TRACE {
                    self.state.m_next_state = self.state.m_int_next_state;
                    }
                    self.state.m_movemr = (self.state.m_dbin) & 0xffff;
                    self.state.m_pc = self.state.m_au;
                    self.state.m_ftu = (self.state.m_dbin) & 0xffff;
                    self.state.m_au = (self.state.m_au).wrapping_add(2);
                    // alu r=0 c=1 m=.....  i=....... 1 a=31:m_dbin d=0
                    self.alu_and(self.state.m_dbin, 0x0000);
                    self.m_icount -= 2;
                    // 27b rset2
                    self.state.m_ir = (self.state.m_irc) & 0xffff;
                    self.state.m_au = (ext32(self.state.m_aluo)).wrapping_sub(2);
                    self.m_icount -= 2;
                    bus.m68000_reset_line(true);
                    label = RSET3;
                    continue;
                }
                RSET3 => {
                    // 0e4 rset3
                    self.state.m_au = (self.state.m_au).wrapping_sub(2);
                    self.m_icount -= 2;
                    // 114 rset4
                    self.state.m_t = u32::from((self.state.m_au & 0x3f) == 0);
                    self.m_icount -= 2;
                    if (self.state.m_t) != 0 {
                    label = RSET5;
                    continue;
                    }
                    else {
                    label = RSET3;
                    continue;
                    }
                    label = RSET5;
                    continue;
                }
                RSET5 => {
                    bus.m68000_reset_line(false);
                    // 064 rset5
                    self.state.m_aob = self.state.m_pc;
                    self.state.m_ird = (self.state.m_ir) & 0xffff;
                    if self.state.m_next_state != S_TRACE {
                    self.state.m_next_state = self.state.m_int_next_state;
                    }
                    self.state.m_au = (self.state.m_pc).wrapping_add(2);
                    self.state.m_base_ssw = (SSW_PROGRAM | SSW_R) & 0xffff;
                    self.state.m_edb = (self.read_program(bus, self.state.m_aob & !1, 0xffff)) & 0xffff;
                    self.m_icount -= 4;
                    if self.m_icount <= 0 {
                    if self.access_to_be_redone() {
                    self.m_icount += 4;
                    self.state.m_inst_substate = 1;
                    } else {
                    self.state.m_inst_substate = 2;
                    }
                    return;
                    }
                    if (self.state.m_aob & 1) != 0 {
                    self.m_icount -= 4;
                    self.state.m_inst_state = S_ADDRESS_ERROR;
                    return;
                    }
                    self.state.m_irc = (self.state.m_edb) & 0xffff;
                    self.state.m_dbin = (self.state.m_edb) & 0xffff;
                    self.set_ftu_const();
                    self.state.m_inst_state = if self.state.m_next_state != 0 { self.state.m_next_state } else { self.m_decode_table[self.state.m_ird as usize] };
                    if (self.state.m_sr & SR_T) != 0 {
                    self.state.m_next_state = S_TRACE;
                    }
                    return;
                }
                _ => unreachable!(),
            }
        }
    }
