        self.alu_and(self.state.m_da[rx], self.state.m_dbin);
        self.sr_nzvc();
        self.state.m_base_ssw = (SSW_PROGRAM | SSW_R) & 0xffff;
        self.state.m_edb = (self.read_program(bus, self.state.m_aob & !1, 0xffff)) & 0xffff;
        self.m_icount -= 4;
        if self.m_icount <= 0 {
            if self.access_to_be_redone() {
                self.m_icount += 4;
                self.state.m_inst_substate = 7;
            } else {
                self.state.m_inst_substate = 8;
            }
            return;
        }
