                    // 1e0 aixl5
                    self.state.m_au = (self.state.m_da[self.map_sp(self.state.m_irc >> 12)]).wrapping_add(self.state.m_au);
                    // alu r=4 c=0 m=.....  i=....... 1 a=none d=5:m_da[map_sp(m_irc >> 12)]
                    self.state.m_base_ssw = (SSW_PROGRAM | SSW_R) & 0xffff;
